// Lab 12.1, provided (you do not edit this file): the bandwidth reference for the benchmark.
// A plain copy of n keys reads 4n bytes and writes 4n bytes, which is what a filter that
// keeps every key must move at least. CUDA; also built for HIP and the CPU emulators.
#ifndef BLOCK_DIM
#define BLOCK_DIM 256
#endif

// region: copy
__global__ void copyKeysKernel(const unsigned int* input, unsigned int* output, unsigned int n) {
    unsigned int i = blockIdx.x*blockDim.x + threadIdx.x;
    if(i < n) {
        output[i] = input[i];
    }
}
// endregion

void launchCopyKeys(const unsigned int* input, unsigned int* output, unsigned int n) {
    if(n == 0) return;
    copyKeysKernel<<<(n + BLOCK_DIM - 1) / BLOCK_DIM, BLOCK_DIM>>>(input, output, n);
}
